#!/bin/sh
# Generates the command-line reference (docs/src/reference/cli.md) from the
# binary's own --help output, so the docs can never drift from the code.
#
#   scripts/gen-cli-docs.sh [path/to/devsync] > docs/src/reference/cli.md
set -eu

bin=${1:-target/debug/devsync}
[ -x "$bin" ] || { echo "error: $bin not found; run cargo build first" >&2; exit 1; }

commands="init push watch exec submit logs jobs kill collect pull ls tree select unselect status changes doctor forward shell setup completions"

cat <<'EOF'
# Command line

<!-- Generated by scripts/gen-cli-docs.sh from `devsync --help`. Do not edit by hand. -->

Every command accepts the global options `-C <dir>` (run as if started in
`<dir>`), `--json` (machine-readable output), `-v` (verbose) and `-q`
(quiet). Commands find the project by looking for `.devsync.toml` in the
current directory and its parents.

| Command | Purpose |
| --- | --- |
EOF

# Summary table from the top-level help.
"$bin" --help | awk '
  /^Commands:/ { on = 1; next }
  on && /^$/ { exit }
  on && $1 != "help" {
    name = $1; $1 = ""; sub(/^ +/, "");
    printf "| [`%s`](#devsync-%s) | %s |\n", name, name, $0
  }'

echo
echo "## devsync"
echo
echo '```text'
"$bin" --help | sed 's/[[:space:]]*$//'
echo '```'

for c in $commands; do
    echo
    echo "## devsync $c"
    echo
    echo '```text'
    "$bin" "$c" --help | sed 's/[[:space:]]*$//'
    echo '```'
done
